import math

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

results = []
max_d = 20  # Set a reasonable initial search limit

print("Searching for pairs (c, d) such that c^2 - 6cd + d^2 is a perfect square.")
print("-" * 50)

for d in range(1, max_d + 1):
    for c in range(1, d):
        s = c**2 - 6*c*d + d**2

        if is_perfect_square(s):
            # Calculate E = c/d + d/c
            e = c/d + d/c
            results.append(((c, d), e))
            print(f"Found pair ({c}, {d}): s = {s} (perfect square). E = {e}")

print("-" * 50)
if results:
    print("Summary of results (Pair, E):")
    for pair, e in results:
        print(f"  {pair}: {e}")
else:
    print("No pairs found within the search limit.")

